node -v && node --input-type=module -e '
import {createPushGate} from "./bot.mjs";
import assert from "node:assert";
const u={id:"u_8841",timeZone:"Asia/Tokyo",quietStart:"22:00",quietEnd:"07:00",dailyCap:3};
const g=createPushGate();
// Tokyo = UTC+9. 12:00 JST = 03:00Z
const at=(h,m=0,d=21)=>new Date(Date.UTC(2026,9,d,h,m));
assert.deepEqual(g.attempt(u,at(3)),{allowed:true,reason:null});
// 22:00 JST = 13:00Z quiet start included; 06:59 JST=21:59Z prev day quiet; 07:00 JST=22:00Z ok
assert.equal(g.attempt(u,at(13,0)).reason,"quiet_hours");
assert.equal(g.attempt(u,at(21,59,21)).reason,"quiet_hours");
assert.equal(g.attempt(u,at(22,0,21)).allowed,true);
assert.equal(g.attempt(u,at(23,0,21)).allowed,true);
assert.equal(g.attempt(u,at(0,0,22)).reason,"daily_cap_reached"); // 3 sent on Oct 22 JST? 07:00,08:00,09:00 -> yes, 4th blocked
// next local day resets: 07:00 JST Oct 23
assert.equal(g.attempt(u,at(22,0,22)).allowed,true);
// UTC-day boundary is not the user day: 00:30Z Oct 22 = 09:30 JST same day as above, cap hit
assert.equal(createPushGate().attempt({...u,timeZone:"Nope/Zone"},at(3)).reason,"invalid_time_zone");
assert.equal(createPushGate().attempt({...u,quietStart:"25:00"},at(3)).reason,"invalid_quiet_hours");
assert.equal(createPushGate().attempt({...u,dailyCap:0},at(3)).reason,"daily_cap_reached");
// independent gates
assert.equal(createPushGate().attempt(u,at(3)).allowed,true);
// DST: New York, same-day window 01:30 local on fall-back day twice (Nov 1 2026)
const ny={id:"n",timeZone:"America/New_York",quietStart:"01:00",quietEnd:"02:00",dailyCap:9};
assert.equal(createPushGate().attempt(ny,new Date("2026-11-01T05:30:00Z")).reason,"quiet_hours");
assert.equal(createPushGate().attempt(ny,new Date("2026-11-01T06:30:00Z")).reason,"quiet_hours");
assert.equal(createPushGate().attempt(ny,new Date("2026-11-01T07:00:00Z")).allowed,true);
console.log("ok");'

